ROOT = pathlib.Path("football-manager/h5")
def download(name):
    target = ROOT / name
    if target.exists() and target.stat().st_size: return
    for attempt in range(4):
        try:
            request = urllib.request.Request(BASE + name, headers={"User-Agent":"Mozilla/5.0", "Referer":"https://activity-static.hupu.com/"})
            with urllib.request.urlopen(request, timeout=60) as response: content = response.read()
            if not content or content[:15].lower().startswith((b"<!doctype",b"<html")): raise ValueError("Invalid image: "+name)
            target.write_bytes(content)
            return
        except Exception:
            if attempt == 3: raise
            time.sleep(2 * (attempt+1))
with concurrent.futures.ThreadPoolExecutor(max_workers=12) as pool:
    list(pool.map(download, FILES))
for name in FILES:
    if not (ROOT/name).exists(): raise RuntimeError("Missing image: "+name)
loader = ROOT / "loader.js"
code = loader.read_text()
if "code.replaceAll" not in code:
    code = code.replace("const code=", "let code=").replace("const url=URL.createObjectURL", 'code=code.replaceAll("'+BASE+'","./h5/");const url=URL.createObjectURL')
    loader.write_text(code)
css = ROOT / "styles.css"
with urllib.request.urlopen(BASE+"styles.css?v=0.5.206", timeout=60) as response:
    style = response.read().decode()
# Restore original CSS, including quoted inline SVGs; all image files stay beside the stylesheet.
css.write_text(style)
index = pathlib.Path("football-manager/index.html")
code = index.read_text().replace(BASE,"./h5/").replace("styles.css?v=0.5.206","styles.css?v=local-images-3").replace('loader.js"','loader.js?v=local-images-3"')
index.write_text(code)
pathlib.Path("football-manager/README.md").write_text("# 绿茵传奇经理\n\n原版游戏逻辑，奖励点击领取，IndexedDB 本地存档。代码、资料和全部图片均由本仓库提供。\n")
print("Cached",len(FILES),"images; all image URLs are same-origin.")
